using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Platform;
using PeopleHub.Application.Modules.Talent;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class TrainingEvidenceTests
{
 class User(int employee=1,bool hr=true,bool company=true):ICurrentUser{public string Email=>"training@example.local";public int? EmployeeId=>employee;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>p==Perm.TalentManage?hr:p==Perm.ScopeCompany&&company;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static TrainingEvidence S(AppDbContext d,User? u=null){u??=new();var c=new AppClock(TimeProvider.System);return new(d,u,c,new AuditService(d,u,c),new AttachmentService(d,new AccessScope(d,u),u,c));}
 static async Task<int> Enroll(AppDbContext d,bool complete=true){var c=await d.Set<TrainingCourse>().FirstAsync();var e=new TrainingEnrollment{EmployeeId=6,CourseId=c.Id,Completed=complete};d.Add(e);await d.SaveAsync();return e.Id;}
 static byte[] Pdf=>"%PDF-1.4\nFictional certificate\n%%EOF"u8.ToArray();
 [Fact]public async Task CertificateRetainsPrivateEvidenceAndExpiry(){await using var d=await Db();var id=await Enroll(d);await S(d).CertificateAsync(id,"Demo issuer","DEMO-37",new(2026,1,1),new(2026,11,1),"demo.pdf",Pdf);var cert=Assert.Single((await S(d).GetAsync()).Certificates);Assert.Equal(new DateTime(2026,11,1),cert.ExpiresOn);var owner=new User(6,false,false);var c=new AppClock(TimeProvider.System);Assert.Equal(Pdf,(await new AttachmentService(d,new AccessScope(d,owner),owner,c).GetAsync(cert.AttachmentToken)).Data);var outsider=new User(4,false,true);Assert.Empty((await S(d,outsider).GetAsync()).Certificates);await Assert.ThrowsAsync<DomainException>(()=>new AttachmentService(d,new AccessScope(d,outsider),outsider,c).GetAsync(cert.AttachmentToken));}
 [Fact]public async Task CompletionAndDatesAndFileSignatureAreRequired(){await using var d=await Db();var id=await Enroll(d,false);await Assert.ThrowsAsync<DomainException>(()=>S(d).CertificateAsync(id,"Issuer","Ref",new(2026,1,1),null,"demo.pdf",Pdf));(await d.Set<TrainingEnrollment>().FindAsync(id))!.Completed=true;await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).CertificateAsync(id,"Issuer","Ref",new(2026,1,1),new(2025,1,1),"demo.pdf",Pdf));await Assert.ThrowsAsync<DomainException>(()=>S(d).CertificateAsync(id,"Issuer","Ref",new(2026,1,1),null,"demo.pdf",[1,2,3]));Assert.Empty(await d.Set<TrainingCertificate>().ToListAsync());}
 [Fact]public async Task ParticipantAndIndependentReviewerEvidenceStayAppendOnly(){await using var d=await Db();var id=await Enroll(d);await S(d,new(6,false,false)).OutcomeAsync(id,"Participant","Applied learning in fictional exercise");await Assert.ThrowsAsync<DomainException>(()=>S(d,new(6,true)).OutcomeAsync(id,"Effectiveness","Self approval"));await S(d).OutcomeAsync(id,"Effectiveness","Observed fictional practice evidence");Assert.Equal(2,(await S(d,new(6,false,false)).GetAsync()).Outcomes.Count);var item=await d.Set<TrainingOutcome>().FirstAsync();item.Note="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>d.SaveAsync());}
 [Fact]public async Task CompanyScopeDoesNotGrantCertificateCreationOrParticipantAuthorship(){await using var d=await Db();var id=await Enroll(d);await Assert.ThrowsAsync<DomainException>(()=>S(d,new(4,false)).CertificateAsync(id,"Issuer","Ref",new(2026,1,1),null,"demo.pdf",Pdf));await Assert.ThrowsAsync<DomainException>(()=>S(d).OutcomeAsync(id,"Participant","Cannot speak as participant"));Assert.Empty(await d.Set<TrainingOutcome>().ToListAsync());}
}
